 void image(JSONObject p,ImageView view){String id=p.optString("id"),url=p.optString("img");view.setTag(url);Bitmap cached=bitmaps.get(url);if(cached!=null){view.setImageBitmap(cached);return;}images.submit(()->{Bitmap b=null;try{JSONObject packed=bundled.optJSONObject(id);if(packed!=null&&packed.optInt("length")>0)b=BitmapFactory.decodeByteArray(photoPack,packed.getInt("offset"),packed.getInt("length"));}catch(Exception ignored){}if(b!=null){final Bitmap local=b;bitmaps.put(url,b);main.post(()->{if(url.equals(view.getTag()))view.setImageBitmap(local);});if(bundled.optJSONObject(id)!=null&&bundled.optJSONObject(id).optString("url").equals(url))return;}try{Uri u=Uri.parse(url.startsWith("/")?NativeStore.ORIGIN+url:url);if(!"https".equals(u.getScheme()))return;File cache=new File(getCacheDir(),"image-"+Integer.toHexString(url.hashCode()));if(!cache.exists()){HttpURLConnection c=(HttpURLConnection)new URL(u.toString()).openConnection();c.setConnectTimeout(9000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)return;byte[] bytes=readBytes(c.getInputStream(),3*1024*1024);BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);opts.inJustDecodeBounds=false;opts.inSampleSize=Math.max(1,Math.max(opts.outWidth,opts.outHeight)/800);b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);if(b!=null)try(FileOutputStream out=new FileOutputStream(cache)){b.compress(Bitmap.CompressFormat.JPEG,83,out);}}finally{c.disconnect();}}else b=BitmapFactory.decodeFile(cache.toString());if(b!=null){bitmaps.put(url,b);final Bitmap ready=b;main.post(()->{if(url.equals(view.getTag()))view.setImageBitmap(ready);});}}catch(Exception ignored){} });}
 byte[] readBytes(InputStream stream,int limit)throws IOException{try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>limit)throw new IOException();out.write(b,0,n);}return out.toByteArray();}}
 void detail(JSONObject p){begin("detail",p.optString("name"));backButton(()->showCatalog(false));ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);photo.setBackground(shape(Color.WHITE,18));page.addView(photo,new LinearLayout.LayoutParams(-1,dp(300)));image(p,photo);page.addView(text(p.optString("brand")+" · "+p.optString("type"),15,MUTED));page.addView(text(money(p.optDouble("price")),29,WINE));page.addView(text(money(pix(p.optDouble("price")))+" no Pix · 5% de desconto",17,0xff397059));page.addView(text("No cartão: até 3x sem juros no checkout seguro.",13,MUTED));page.addView(text("Sob encomenda: preparação em até 10 dias úteis antes do transporte.",14,INK));Button add=button(sellable(p)?"Adicionar à sacola":"Indisponível",()->{if(requireLogin())addCart(p);});add.setEnabled(sellable(p));page.addView(add);page.addView(secondary(favorites.contains(p.optString("id"))?"♥ Salvo nos favoritos":"♡ Favoritar",()->{if(!requireLogin())return;String id=p.optString("id");if(favorites.contains(id))favorites.remove(id);else favorites.add(id);saveFavorites();detail(p);}));page.addView(secondary("Compartilhar perfume",()->{Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,p.optString("name")+" — Valenza Parfums\n"+NativeStore.ORIGIN+"/perfume/"+Uri.encode(p.optString("id"))+"/");startActivity(Intent.createChooser(send,"Compartilhar perfume"));}));gap(page,15);page.addView(title("Conheça a fragrância"));page.addView(text(p.optString("desc"),15,INK));TextView details=text("",14,MUTED);details.setText(android.text.Html.fromHtml(p.optString("details"),android.text.Html.FROM_HTML_MODE_LEGACY));page.addView(details);}
 void addCart(JSONObject p){try{int qty=1;for(int i=0;i<cart.length();i++)if(cart.getJSONObject(i).getString("id").equals(p.optString("id"))){qty=cart.getJSONObject(i).optInt("qty",1)+1;if(qty>Math.min(10,p.has("stock")?p.optInt("stock",10):10)){notice("Quantidade máxima disponível atingida.");return;}cart.getJSONObject(i).put("qty",qty);saveCart();toast("Adicionado à sacola.");return;}cart.put(j("id",p.optString("id"),"qty",1));saveCart();toast("Adicionado à sacola.");}catch(Exception e){notice("Não foi possível atualizar a sacola.");}}
